sites.find:
do {
    --post_cursor;
    RenderableBod* bod = *post_cursor;
    unsigned int bod_flags = bod->list_flags;
    if ((bod_flags & BOD_FLAG_USE_TRANSFORM) != 0) {
        render_object(
            bod->object,
            &bod->transform,
            bod->render_arg_1c,
            bod->render_arg_20,
            &bod->color,
            (char)bod->IsAfterSprites());
    } else {
        Vector3 position = bod->position;
        transform.position = position;
        render_object(
            bod->object,
            &transform,
            bod->render_arg_1c,
            bod->render_arg_20,
            &bod->color,
            (char)bod->IsAfterSprites());
    }
    --replay_count;
} while (replay_count != 0);

